[{"order":1,"type":"heading","text":"Building Multiplatform Apps with SwiftUI: macOS, watchOS, and visionOS"},{"order":2,"type":"paragraph","text":"SwiftUI provides a unified declarative syntax that allows developers to target Apple's entire ecosystem. While iOS is the most common starting point, extending your application to macOS, watchOS, and visionOS requires understanding platform-specific idioms, navigation models, and interaction paradigms."},{"order":3,"type":"heading","text":"Adapting UI for macOS"},{"order":4,"type":"paragraph","text":"macOS applications typically feature multi-window workflows, menu bars, sidebars, and keyboard shortcuts. To build a robust Mac app using SwiftUI, you utilize scenes like WindowGroup and navigation structures tailored for desktop displays."},{"order":5,"type":"code","text":"import SwiftUI

struct MacContentView: View {
    var body: some View {
        NavigationSplitView {
            List {
                Text("Inbox")
                Text("Sent")
            }
            .navigationTitle("Mail")
        } detail: {
            Text("Select an item")
        }
    }
}"},{"order":6,"type":"heading","text":"Designing for watchOS"},{"order":7,"type":"paragraph","text":"The Apple Watch requires concise, glanceable interfaces. watchOS uses vertical scrolling lists, paging styles, and distinct navigation containers. Complex hierarchies should be flattened to ensure a smooth user experience on the wrist."},{"order":8,"type":"code","text":"import SwiftUI

struct WatchContentView: View {
    var body: some View {
        TabView {
            VStack {
                Text("Activity")
                    .font(.headline)
                Text("320/500 KCAL")
            }
            VStack {
                Text("Heart Rate")
                    .font(.headline)
                Text("72 BPM")
            }
        }
        .tabViewStyle(.page)
    }
}"},{"order":9,"type":"heading","text":"Embracing Spatial Computing in visionOS"},{"order":10,"type":"paragraph","text":"visionOS introduces spatial computing, where windows float in a 3D room, and interactions rely on eyes and hands. SwiftUI integrates deeply with RealityKit to display 3D models alongside standard UI elements."},{"order":11,"type":"code","text":"import SwiftUI
import RealityKit

struct VisionContentView: View {
    var body: some View {
        VStack(spacing: 20) {
            Text("Welcome to visionOS")
                .font(.extraLargeTitle)

            Model3D(named: "Scene")
                .frame(depth: 300)

            Toggle("Immersive Space", isOn: .constant(false))
                .toggleStyle(.button)
        }
        .padding()
    }
}"},{"order":12,"type":"heading","text":"Platform Conditional Compilation"},{"order":13,"type":"paragraph","text":"When code sharing reaches its limit, you can use Swift conditional compilation directives to inject platform-specific modifiers and views."},{"order":14,"type":"code","text":"struct PlatformSpecificButton: View {
    var body: some View {
        Button("Action") {
            print("Clicked")
        }
        #if os(macOS)
        .buttonStyle(.borderedProminent)
        #elseif os(watchOS)
        .buttonStyle(.bordered)
        #endif
    }
}"},{"order":15,"type":"heading","text":"Best Practices for Multiplatform Development"},{"order":16,"type":"bullet_point","text":"Separate business logic into shared ViewModels or packages."},{"order":17,"type":"bullet_point","text":"Design adaptive layouts rather than hardcoding frames."},{"order":18,"type":"bullet_point","text":"Test input methods thoroughly (mouse/keyboard for Mac, Digital Crown for watch, gestures for visionOS)."}]
